class Solution {
  public long minimumCost(int[] nums, int k, int dist) {
    int n = nums.length;
    // coordinate-compress the values and keep count / sum Fenwick trees over them
    int[] sorted = nums.clone();
    Arrays.sort(sorted);
    int[] rank = new int[n];
    for (int i = 0; i < n; i++)
      rank[i] = Arrays.binarySearch(sorted, nums[i]) + 1; // duplicates share a slot
    int size = n;
    long[] countTree = new long[size + 1], sumTree = new long[size + 1];
    int need = k - 2; // smallest values besides nums[p] that join the first cut
    long best = Long.MAX_VALUE;
    int windowEnd = 1; // exclusive end of window [p + 1, p + dist]
    int windowSize = 0;
    for (int p = 1; p < n; p++) {
      // window of candidates: indices p + 1 .. min(n - 1, p + dist)
      if (p > 1 && p <= n - 1) {
        // remove index p (it became the chosen start for this p)
        update(countTree, sumTree, rank[p], nums[p], -1);
        windowSize--;
      }
      int limit = Math.min(n - 1, p + dist);
      if (windowEnd <= p) windowEnd = p + 1;
      while (windowEnd <= limit) {
        update(countTree, sumTree, rank[windowEnd], nums[windowEnd], 1);
        windowSize++;
        windowEnd++;
      }
      if (windowSize < need) continue;
      best = Math.min(best, (long) nums[p] + smallest(countTree, sumTree, need, size));
    }
    return nums[0] + best;
  }

  private void update(long[] count, long[] sum, int i, long value, int sign) {
    for (; i < count.length; i += i & -i) {
      count[i] += sign;
      sum[i] += sign * value;
    }
  }

  // sum of the `need` smallest values currently stored
  private long smallest(long[] count, long[] sum, int need, int size) {
    if (need == 0) return 0;
    int pos = 0, step = Integer.highestOneBit(size);
    long taken = 0, total = 0;
    for (; step > 0; step >>= 1) {
      int next = pos + step;
      if (next <= size && taken + count[next] < need) {
        pos = next;
        taken += count[next];
        total += sum[next];
      }
    }
    // the next slot holds the remaining copies, all with the same value
    long value = valueAt(sum, count, pos + 1, size);
    return total + (need - taken) * value;
  }

  private long valueAt(long[] sum, long[] count, int slot, int size) {
    // a slot's single value = (prefix sum) difference / count; recover it from the two prefix
    // queries
    long c = 0, s = 0;
    for (int i = slot; i > 0; i -= i & -i) {
      c += count[i];
      s += sum[i];
    }
    long c2 = 0, s2 = 0;
    for (int i = slot - 1; i > 0; i -= i & -i) {
      c2 += count[i];
      s2 += sum[i];
    }
    return (s - s2) / (c - c2);
  }
}
